import{_ as e}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as o}from"./chunks/OFF.BrU7kQE-.js";import{_ as a}from"./chunks/EN.P9aPnFBv.js";import{_ as s,a as l}from"./chunks/M-S-MT5a.Dak_k1ZE.js";import{_ as i}from"./chunks/DIS.DdpTdGGD.js";import{_ as n,o as m,c as p,a3 as r}from"./chunks/framework.g9mfNVRQ.js";const A=JSON.parse('{"title":"Rilevazione movimento","description":"","frontmatter":{"source_hash":"55194cb270","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/use/motion.md","filePath":"it/use/motion.md"}'),d={name:"it/use/motion.md"};function c(u,t,v,_,g,f){return m(),p("div",null,[...t[0]||(t[0]=[r('<div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_car_connected_grey600_48dp.png" style="width:5%;"> Rilevazione Movimento xDrip+</p></div><p>La rilevazione del movimento serve a riconoscere la modalità veicolo e ad aggiungere funzioni quando guidi l&#39;auto.</p><div class="admonition xdripitem"><p class="admonition-title">Abilita Rilevazione Movimento<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Usa i sensori per rilevare i tipi di movimento</p></div><p>Puoi visualizzare il movimento sul grafico principale.</p><div class="admonition xdripitem"><p class="admonition-title">Salva e traccia movimento <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Memorizza i tipi di movimento recenti e tracciali sul grafico principale</p></div><img src="'+s+'" style="zoom:75%;"><p>Come per xDrip Sync, puoi definire quale telefono invierà effettivamente le informazioni sul movimento: sarà il master del movimento, e solo un dispositivo può essere master. Puoi impostare un dispositivo come follower del movimento per monitorare a distanza il movimento del dispositivo master.</p><div class="admonition xdripitem"><p class="admonition-title">Usa movimento remoto <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Dati di movimento presi dal telefono remoto invece di quello locale</p></div><div class="admonition xdripitem"><p class="admonition-title">Agisci come master per il movimento <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Diventa il master per il movimento anche se siamo follower. Impostare solo so un telefono!</p></div><p>La modalità veicolo attiva altre opzioni.</p><div class="admonition xdripitem"><p class="admonition-title">Abilita modalità veicolo<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Quando viene rilevata la presenza in un veicolo, abilita funzionalità supplementari</p></div><img src="'+l+'" style="zoom:75%;"><p>Puoi attivare automaticamente la modalità veicolo quando ti connetti al sistema audio Bluetooth dell&#39;auto.<br> Puoi anche impostarla manualmente identificando la connessione Bluetooth dell&#39;audio dell&#39;auto.</p><div class="admonition xdripitem"><p class="admonition-title">Rileva audio dell&#39;auto<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Abilita automaticamente la modalità veicolo quando connesso al bluetooth dell&#39;auto</p></div><div class="admonition xdripitem"><p class="admonition-title">Riconosci l&#39;audio attuale dell&#39;auto</p><p> Tocca per impostare il dispositivo audio auto attualmente connesso</p></div><p>Alzare la soglia dell&#39;allarme di glicemia bassa ti permette di essere avvisato a un livello più alto di quello impostato negli allarmi.</p><div class="admonition xdripitem"><p class="admonition-title">Aumenta la soglia &#39;Glicemia bassa&#39; <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Aumenta il volume degli allarmi bassi quando in modalità veicolo</p></div><p>Puoi fare in modo che xDrip attivi automaticamente le letture vocali quando guidi.</p><div class="admonition xdripitem"><p class="admonition-title">Letture Vocali <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Abilita la lettura vocale quando sei in modalità veicolo</p></div><p>Puoi far riprodurre un suono quando passa alla modalità di rilevazione del movimento e un suono di promemoria ogni 90 minuti.</p><div class="admonition xdripitem"><p class="admonition-title">Suona <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Suono di notifica quando è stata rilevata la modalità veicolo</p></div><div class="admonition xdripitem"><p class="admonition-title">Ripeti il suono <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Ripeti il suono di notifica ogni 90 minuti se ancora in modalità veicolo</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',24)])])}const P=n(d,[["render",c]]);export{A as __pageData,P as default};
